<template><view class="page"><view class="hero"><text class="title">AI对话练习</text><text class="sub">模拟真实场景，锻炼口语反应</text></view><view class="dialogue"><view class="head"><text>{{scene.name}}</text><text class="tag">进行中</text></view><view v-for="(m,i) in messages" :key="i" class="msg"><text class="avatar">🤖</text><view class="bubble"><text>{{m.text}}</text><text class="sound" @click="play(m.text)">🔊</text></view></view><view class="input"><input v-model="input" placeholder="输入想说的话…"/><button @click="send">发送</button></view></view></view></template><script>export default{data(){return{scene:{name:'餐厅点餐'},messages:[{text:'Hello! Welcome to our restaurant. Are you ready to order?'}],input:'',audio:null}},methods:{send(){if(!this.input.trim())return;this.messages.push({text:this.input.trim()});this.input=''},play(text){if(this.audio)this.audio.destroy();const a=uni.createInnerAudioContext();a.src='https://dict.youdao.com/dictvoice?type=1&audio='+encodeURIComponent(text);a.onCanplay(()=>a.play());a.onError(()=>uni.showToast({title:'音频加载失败',icon:'none'}));this.audio=a}},onReady(){this.$nextTick(()=>this.play(this.messages[0].text))}}</script><style>.page{min-height:100vh;background:#f7f5f0;padding:28rpx}.hero{text-align:center;padding:20rpx}.title{display:block;font-size:42rpx;font-weight:800;color:#1f3a5f}.sub{color:#999;font-size:26rpx}.dialogue{background:#fff;border-radius:20rpx;padding:24rpx}.head{display:flex;justify-content:space-between;color:#1f3a5f;font-weight:bold}.tag{color:#0d9488}.msg{display:flex;margin:28rpx 0}.avatar{font-size:38rpx;margin-right:14rpx}.bubble{flex:1;background:#f1f5f9;border-radius:16rpx;padding:20rpx;color:#334155}.sound{float:right;margin-left:12rpx}.input{display:flex;gap:12rpx;margin-top:25rpx}.input input{flex:1;background:#f1f5f9;border-radius:12rpx;padding:18rpx}.input button{background:#0d9488;color:#fff}</style>
